// CustomHealthIndicator.java
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

@Component
public class ExternalServiceHealthIndicator implements HealthIndicator {

    @Override
    public Health health() {
        // Simulate external check
        boolean isUp = checkExternalService();
        if (isUp) {
            return Health.up()
                    .withDetail("service", "api.example.com")
                    .withDetail("status", "available")
                    .build();
        } else {
            return Health.down()
                    .withDetail("service", "api.example.com")
                    .withDetail("status", "unreachable")
                    .build();
        }
    }

    private boolean checkExternalService() {
        // In real code, use RestTemplate
        return true; // Simulate success
    }
}

// CustomInfoContributor.java
import org.springframework.boot.actuate.info.Info;
import org.springframework.boot.actuate.info.InfoContributor;
import org.springframework.stereotype.Component;
import java.time.LocalDateTime;
import java.util.Map;

@Component
public class CustomInfoContributor implements InfoContributor {

    @Override
    public void contribute(Info.Builder builder) {
        builder.withDetail("build", Map.of(
            "artifact", "demo",
            "version", "1.0.0",
            "timestamp", LocalDateTime.now().toString()
        ));
    }
}

// To secure (optional)
// Add spring-boot-starter-security and configure:
@Bean
public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.authorizeRequests()
        .antMatchers("/actuator/health", "/actuator/info").permitAll()
        .antMatchers("/actuator/**").hasRole("ADMIN")
        .anyRequest().authenticated()
        .and()
        .httpBasic();
    return http.build();
}
